{"qas": [
  {"question": "According to the IBM AI Risk Atlas, how can AI agents' redundant actions impact both computational resources and the environment?", "answer": "Redundant actions by AI agents can waste computational resources and increase environmental impact through added carbon emissions.", "evidence": [{"page": 23, "quote": "Executing actions that are not needed for the goal might result in wasting computation resources, increased cost, reducing AI agent's efficiency in achieving the goal, and leading to potentially harmful outcomes."}, {"page": 23, "quote": "Complexity of the tasks and possibility of AI agents performing redundant actions could lead to computational inefficiencies and add to the environmental impact."}]},
  {"question": "What does the IBM AI Risk Atlas define as 'personal information in data', and what risk does it describe?", "answer": "'Personal information in data' refers to PII or SPI in training or fine-tuning data, risking unwanted disclosure if not properly protected.", "evidence": [{"page": 33, "quote": "Inclusion or presence of personal identifiable information (PII) and sensitive personal information (SPI) in the data used for training or fine tuning the model might result in unwanted disclosure of that information."}]},
  {"question": "How does the IBM AI Risk Atlas describe the consequences of improper retraining?", "answer": "Improper retraining with undesirable output can lead to unexpected model behavior and more undesirable outputs.", "evidence": [{"page": 27, "quote": "Repurposing generated output for retraining a model without implementing proper human vetting increases the chances of undesirable outputs to be incorporated into the training or tuning data of the model. In turn, this model can generate even more undesirable output."}]},
  {"question": "Which attack described in the IBM AI Risk Atlas involves overloading prompts with excessive tokens, and what is its intended effect?", "answer": "A context overload attack overloads the prompt with excessive tokens to predispose models to a vulnerable state.", "evidence": [{"page": 26, "quote": "Overloading the prompt with excessive tokens, for instance with many-shot examples, can predispose models to a vulnerable state."}]},
  {"question": "What is the risk if a model is used for a purpose it was not originally designed for, according to the IBM AI Risk Atlas?", "answer": "Unexpected and unwanted model behaviors may result from improper usage.", "evidence": [{"page": 34, "quote": "Improper usage occurs when a model is used for a purpose that it was not originally designed for."}]},
  {"question": "What term does the IBM AI Risk Atlas use for the inability to access training data for source attribution, and what is the consequence?", "answer": "Untraceable attribution; it makes it difficult or impossible to use source attribution techniques, reducing trust.", "evidence": [{"page": 29, "quote": "Without the ability to access training data content, the possibility of using source attribution techniques can be severely limited or impossible. This makes it difficult for users, model validators, and auditors to understand and trust the model."}]}
]}
